import{_ as o,c as a,o as i,ag as t}from"./chunks/framework.D2yFLINz.js";const p=JSON.parse('{"title":"Changelog","description":"Release notes for ew-color-picker, including fixes, features and documentation updates.","frontmatter":{"title":"Changelog","description":"Release notes for ew-color-picker, including fixes, features and documentation updates."},"headers":[],"relativePath":"guide/changelog.md","filePath":"guide/changelog.md"}'),d={name:"guide/changelog.md"};function n(l,e,c,r,s,h){return i(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><h2 id="_2-0-8" tabindex="-1">2.0.8 <a class="header-anchor" href="#_2-0-8" aria-label="Permalink to &quot;2.0.8&quot;">​</a></h2><h3 id="fixes" tabindex="-1">Fixes <a class="header-anchor" href="#fixes" aria-label="Permalink to &quot;Fixes&quot;">​</a></h3><ul><li>Fixed arrow and close icon positioning for users who load the static CSS via <code>&lt;link&gt;</code>: the icon rules were only injected at runtime by the core entry, so the SCSS build (<code>@ew-color-picker/style</code>) was missing them and the arrow rendered off-center. The rules are now in the SCSS source as well</li><li>Arrow icon <code>fill</code> changed from hard-coded <code>#666666</code> to <code>currentColor</code>, so icons inherit the theme text color</li><li>Fixed the empty root container taking up <code>line-height</code> height when <code>hasBox: false</code> is used together with <code>appendTo</code>: the <code>.ew-color-picker</code> shell is now hidden via <code>:empty { display: none }</code> and reappears automatically once the box is rendered</li><li>Fixed panel positioning when <code>hasBox: false</code>: the panel anchor now falls back from the box to the user-supplied <code>el</code> container (and only then to the root element), so the panel is no longer positioned against a 0-size empty shell</li><li>Fixed <code>showPanel</code>/<code>hidePanel</code> not being idempotent: calling <code>showPanel</code> while the panel was already open re-ran the open animation, which briefly reset the panel height to <code>0</code> and made it look like the panel closed. Both methods now return early when the panel is already in the target state</li></ul><h3 id="docs" tabindex="-1">Docs <a class="header-anchor" href="#docs" aria-label="Permalink to &quot;Docs&quot;">​</a></h3><ul><li>Added npm version, downloads, license, build, TypeScript and stars badges to both READMEs</li><li>Added a live demo screenshot to both READMEs</li></ul><h2 id="_2-0-7" tabindex="-1">2.0.7 <a class="header-anchor" href="#_2-0-7" aria-label="Permalink to &quot;2.0.7&quot;">​</a></h2><h3 id="fixes-1" tabindex="-1">Fixes <a class="header-anchor" href="#fixes-1" aria-label="Permalink to &quot;Fixes&quot;">​</a></h3><ul><li>Fixed the picker panel being covered by overlay masks in Element Plus Dialog and similar layered containers: the panel <code>z-index</code> was fixed at <code>1000</code> in the stylesheet while overlay libraries start at <code>2000</code> and increase on every open. The panel now raises its inline <code>z-index</code> to one above the highest ancestor level each time it opens, leaves normal pages to the stylesheet default, and falls back silently if reading or writing styles fails</li></ul><h3 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h3><ul><li>Added regression tests for automatic <code>z-index</code> elevation inside layered containers, recomputation on repeated opens, and the untouched inline style on normal pages</li></ul><h2 id="_2-0-6" tabindex="-1">2.0.6 <a class="header-anchor" href="#_2-0-6" aria-label="Permalink to &quot;2.0.6&quot;">​</a></h2><h3 id="fixes-2" tabindex="-1">Fixes <a class="header-anchor" href="#fixes-2" aria-label="Permalink to &quot;Fixes&quot;">​</a></h3><ul><li>Fixed <code>colorRgbaToHsva</code> turning a valid alpha of <code>0</code> into <code>1</code> (<code>parseFloat(...) || 1</code> treated <code>0</code> as falsy), which made fully transparent colors opaque once hue or saturation/value was adjusted and made <code>getHsvaColor()</code> return <code>a: 1</code></li><li>Fixed <code>colorRgbaToHsla</code> returning <code>colorObj.h</code> on the internal <code>0-6</code> scale instead of degrees, which broke the round trip through <code>colorHslaToRgba</code> (e.g. green <code>rgba(0, 202, 136, 1)</code> came back as <code>rgba(204, 10, 0, 1)</code>)</li></ul><h3 id="tests-1" tabindex="-1">Tests <a class="header-anchor" href="#tests-1" aria-label="Permalink to &quot;Tests&quot;">​</a></h3><ul><li>Added regression tests for the <code>rgba(..., 0)</code> round trip, the unparseable-alpha fallback and the HSL hue / round trip</li></ul><h3 id="release" tabindex="-1">Release <a class="header-anchor" href="#release" aria-label="Permalink to &quot;Release&quot;">​</a></h3><ul><li>Added a GitHub Actions CI workflow running dependency install, the full test suite and a full package build on pushes and pull requests to <code>master</code></li><li>Declared <code>rimraf</code> as a dev dependency of <code>utils</code> and <code>core</code> so clean builds work under pnpm&#39;s strict <code>node_modules</code> layout</li></ul><h2 id="_2-0-5" tabindex="-1">2.0.5 <a class="header-anchor" href="#_2-0-5" aria-label="Permalink to &quot;2.0.5&quot;">​</a></h2><h3 id="fixes-3" tabindex="-1">Fixes <a class="header-anchor" href="#fixes-3" aria-label="Permalink to &quot;Fixes&quot;">​</a></h3><ul><li>Fixed panel positioning inside drawers, modals and scroll containers: new <code>boundary</code> option accepts a CSS selector or HTMLElement, clamping the panel within that container&#39;s visible area instead of only the viewport</li><li>Fixed <code>document.mousedown</code> listener leaking after <code>destroy()</code> when the panel show timer fired after destruction; the callback now bails out if the instance is already destroyed</li><li>Fixed root <code>build:xxx</code> shortcuts silently doing nothing (<code>pnpm -r build:xxx</code> matched no package scripts); replaced with <code>pnpm --filter &lt;pkg&gt; build</code> and added missing shortcuts for gradient, select, checkbox, copy-color and input-number</li></ul><h3 id="refactor" tabindex="-1">Refactor <a class="header-anchor" href="#refactor" aria-label="Permalink to &quot;Refactor&quot;">​</a></h3><ul><li>Consolidated drag logic into <code>utils/drag.ts</code>: new <code>getRatio</code>, <code>bindMouseDrag</code> and <code>bindTouchDrag</code> utilities, reused by hue, alpha, panel and gradient; eliminates ~10 <code>as EventListener</code> casts</li><li>Extracted <code>DEFAULT_PANEL_WIDTH</code> / <code>DEFAULT_PANEL_HEIGHT</code> constants, replacing 7 hard-coded <code>285 / 180</code> occurrences across panel and gradient</li><li>Unified on utility functions: <code>isString</code> / <code>isObject</code> / <code>isBoolean</code> / <code>isNumber</code> replace raw <code>typeof</code> checks; <code>$</code> and <code>getRect</code> replace direct <code>querySelector</code> / <code>getBoundingClientRect</code> calls</li><li>Removed <code>as any</code> casts in plugin options initialization; <code>install(core: any)</code> aligned to <code>install(core: ewColorPicker)</code> across all plugins</li><li><code>getPrefix</code> now uses <code>isString</code> and accepts <code>ewColorPicker</code> instance type instead of <code>any</code></li><li>Removed unused <code>eventType</code> dead code from utils</li><li>Documented the implicit <code>applyOrder</code> sorting convention: plugins without <code>applyOrder</code> default to 0 and run before all <code>Post</code> plugins</li></ul><h3 id="docs-1" tabindex="-1">Docs <a class="header-anchor" href="#docs-1" aria-label="Permalink to &quot;Docs&quot;">​</a></h3><ul><li>Added <code>boundary</code> option documentation (English and Chinese) with usage examples</li><li>Added example page <code>18-panel-boundary.html</code> demonstrating container-bound panel positioning</li><li>Fixed docs site footer friend links showing Chinese text on the English version</li><li>Added missing example navigation links (15-18) to the examples index</li></ul><h3 id="release-1" tabindex="-1">Release <a class="header-anchor" href="#release-1" aria-label="Permalink to &quot;Release&quot;">​</a></h3><ul><li>Added <code>prepublishOnly: &quot;npm run build&quot;</code> to all packages so dist is rebuilt before every publish</li></ul><h2 id="_2-0-4" tabindex="-1">2.0.4 <a class="header-anchor" href="#_2-0-4" aria-label="Permalink to &quot;2.0.4&quot;">​</a></h2><h3 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li>New <code>@ew-color-picker/select</code> component and plugin: custom option lists with placeholder, sizes, keyboard navigation, click-outside closing and ARIA support, an optional clear icon via <code>selectClearable</code>, and <code>selectItems</code> / <code>selectValue</code> / <code>selectPlaceholder</code> / <code>onSelectChange</code> / <code>onSelectClear</code> options. Renders only when <code>selectItems</code> is non-empty</li><li>New <code>@ew-color-picker/gradient</code> plugin: a gradient editor with draggable stops, linear/radial/conic types, repeating gradients, angle and position controls, double-position stops, and interpolation hints (<code>srgb</code>, <code>srgb-linear</code>, <code>hsl</code>, <code>oklab</code>, <code>oklch</code>). CSS strings round-trip through <code>parseGradient</code> / <code>serializeGradient</code>, and the editor is hidden unless <code>showGradient: true</code> or <code>gradient</code> / <code>gradientStops</code> is provided</li><li>New <code>@ew-color-picker/checkbox</code> component and plugin: replaces the native checkbox visual with a themed box while keeping the underlying native input for semantics and keyboard support. The plugin renders in the bottom row when <code>checkboxLabel</code> is provided and supports <code>showCheckbox</code> / <code>checkboxChecked</code> / <code>checkboxDisabled</code> / <code>onCheckboxChange</code></li><li>The aggregate package now exports a <code>createEwColorPicker(options)</code> factory, and the <code>ew-color-picker</code> compat entry exposes the same factory</li></ul><h3 id="fixes-4" tabindex="-1">Fixes <a class="header-anchor" href="#fixes-4" aria-label="Permalink to &quot;Fixes&quot;">​</a></h3><ul><li>Fixed <code>defaultColor</code> handling: instance plugins are not created yet at that point, so the check now reads the static plugin registry to see whether the alpha plugin is registered; without alpha, an rgba default correctly falls back to hex</li><li>Fixed the hue bar background, panel cursor and hue / alpha thumb positions being wrong when the panel opens without an initial color (or with a color set later): everything is re-synced against the current color once the panel is shown</li><li>Fixed the panel width calculation for different hue / alpha direction combinations, which pushed same-row elements onto a new line and misaligned the edges</li><li>Fixed <code>colorRgbaToHsva</code> only accepting rgba strings; it now also handles hex / rgb / color keywords</li><li>Fixed the gradient editor stop-row layout: number inputs clipped their values and the Remove / Add buttons were pushed onto a new line; inputs are now wider with compact steppers and tighter gaps so everything fits on one row</li></ul><h2 id="_2-0-3" tabindex="-1">2.0.3 <a class="header-anchor" href="#_2-0-3" aria-label="Permalink to &quot;2.0.3&quot;">​</a></h2><blockquote><p>This release has been published to npm and the docs site has been updated.</p></blockquote><h3 id="features-1" tabindex="-1">Features <a class="header-anchor" href="#features-1" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li>New <code>@ew-color-picker/eyedropper</code> plugin: sample colors from anywhere on screen through the native EyeDropper API. It detects browser support, writes the result with <code>core.setColor()</code>, supports <code>showEyedropper</code> / <code>eyedropperText</code> / <code>onEyedropperPick</code>, and silently ignores <code>AbortError</code> when the user cancels</li><li>New <code>@ew-color-picker/copy-color</code> plugin: copy the current color to the clipboard with one click. The button is filled with the current color and uses contrast-aware icons, prefers the async Clipboard API with a <code>execCommand</code> fallback, shows a short built-in success toast, and supports <code>showCopyColor</code> / <code>copyColorText</code> / <code>copiedText</code> / <code>onCopyColor</code></li><li>The eyedropper and copy buttons now live in their own toolbar row above the color value input, instead of sharing the row with the Clear / Sure buttons</li></ul><h3 id="fixes-5" tabindex="-1">Fixes <a class="header-anchor" href="#fixes-5" aria-label="Permalink to &quot;Fixes&quot;">​</a></h3><ul><li>Fixed the InputNumber stepper arrows: they now carry the correct icon class and render at 10px, staying centered inside the button instead of overflowing and being clipped by the divider</li><li>Fixed RGB / HSL channel inputs resetting to <code>0</code> on the first stepper click; internal values are now synced with the current color so increment/decrement starts from the current channel value</li></ul><h2 id="_2-0-2" tabindex="-1">2.0.2 <a class="header-anchor" href="#_2-0-2" aria-label="Permalink to &quot;2.0.2&quot;">​</a></h2><h3 id="fixes-6" tabindex="-1">Fixes <a class="header-anchor" href="#fixes-6" aria-label="Permalink to &quot;Fixes&quot;">​</a></h3><ul><li>Published package manifests now reference the matching release version (<code>^2.0.2</code>) for internal dependencies instead of the stale <code>^2.0.0</code> range. This prevents mixed installs where a 2.0.1 plugin resolved an older <code>@ew-color-picker/utils</code> that did not export <code>getPrefix</code></li></ul><h2 id="_2-0-1" tabindex="-1">2.0.1 <a class="header-anchor" href="#_2-0-1" aria-label="Permalink to &quot;2.0.1&quot;">​</a></h2><blockquote><p>These changes have been published to npm and are reflected in the docs site.</p></blockquote><h3 id="fixes-7" tabindex="-1">Fixes <a class="header-anchor" href="#fixes-7" aria-label="Permalink to &quot;Fixes&quot;">​</a></h3><ul><li>Fixed plugin switches being overridden: <code>ewColorPickerPanel: false</code> and <code>ewColorPickerColorMode: false</code> (or an object config) were replaced by defaults and did not take effect</li><li>Panel container now declares <code>box-sizing: content-box</code>, no longer relying on the host global <code>box-sizing</code> reset</li><li>Removed viewport media queries (<code>max-width: 768px</code>) that hard-coded panel, input and preset sizes; inner sizes are now driven solely by <code>--panel-width</code> / <code>--panel-height</code></li><li>Predefined swatches now use flex wrapping; removed the hard-coded &quot;10 per row&quot; rule that caused wrong wrapping when the swatch count or container width changed</li><li><code>use()</code> now deduplicates by <code>pluginName</code>, preventing duplicate registration under HMR, repeated imports or multiple entry points</li><li>Plugin constructor errors are now reported through <code>console.warn</code> with the plugin name and error details instead of being silently swallowed, making custom plugin debugging easier</li></ul><h3 id="features-2" tabindex="-1">Features <a class="header-anchor" href="#features-2" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li>New <code>appendTo</code> option: mount the panel container into <code>document.body</code> or any container to avoid <code>overflow</code> clipping by dialogs, drawers and scroll containers. The panel then uses viewport-relative positioning, still honors <code>panelPlacement</code> with boundary flipping, and re-positions on scroll or resize</li><li>New <code>prefix</code> option: customize the prefix of every CSS class name (default <code>ew-</code>) to avoid style collisions when embedding the picker in another library. The SCSS build exposes a matching <code>$prefix</code> variable that must stay in sync with the JS option</li><li><code>ApplyOrder</code> changed from <code>const enum</code> to a regular enum, so it can be imported at runtime from <code>@ew-color-picker/utils</code> without hand-writing <code>&#39;pre&#39;</code> / <code>&#39;post&#39;</code> strings</li></ul><h3 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h3><ul><li>Corrected predefined swatch and number input class names to match the source</li><li>Removed the non-existent nested <code>ewColorPickerBox</code> config in favor of top-level options</li><li>Corrected the prerequisites of <code>autoPanelPosition</code></li><li>Added <code>appendTo</code> documentation (Chinese and English)</li><li>Added <code>prefix</code> documentation (Chinese and English) with a custom SCSS build example</li><li>Added <code>applyOrder</code> execution-order documentation and examples (Chinese and English)</li><li>The docs site now defaults to English; Chinese docs moved under <code>/zh/</code>, and the README defaults to English</li></ul><h2 id="_2-0-0" tabindex="-1">2.0.0 <a class="header-anchor" href="#_2-0-0" aria-label="Permalink to &quot;2.0.0&quot;">​</a></h2><p>First stable release: core + plugin architecture, 14 packages (13 scoped packages plus the unscoped <code>ew-color-picker</code> entry package), bilingual docs site and live demo.</p>',51)])])}const g=o(d,[["render",n]]);export{p as __pageData,g as default};
